package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.FreeSpaceOpticsKernel;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;public class FreeSpaceOpticalTransmitterBlock extends DirectionalDomainBlock{public static final IntegerProperty CHANNEL=IntegerProperty.create("channel",0,3);public FreeSpaceOpticalTransmitterBlock(Properties p){super(p);registerDefaultState(defaultBlockState().setValue(CHANNEL,0));}@Override public MapCodec<FreeSpaceOpticalTransmitterBlock> codec(){return RedstoneEngineering.FREE_SPACE_OPTICAL_TRANSMITTER_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){super.createBlockStateDefinition(b);b.add(CHANNEL);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,4);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int power=l.getBestNeighborSignal(p);if(power>0)FreeSpaceOpticsKernel.emit(l,p,outputSide(s),power,s.getValue(CHANNEL));l.scheduleTick(p,this,4);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block b,BlockPos q,boolean m){if(l instanceof ServerLevel sl){int power=l.getBestNeighborSignal(p);if(power>0)FreeSpaceOpticsKernel.emit(sl,p,outputSide(s),power,s.getValue(CHANNEL));}}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int c=(s.getValue(CHANNEL)+1)%4;l.setBlock(p,s.setValue(CHANNEL,c),Block.UPDATE_CLIENTS);pl.displayClientMessage(Component.literal("Free-space optical TX channel="+c+" range<=48, LOS required"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}